import subprocess, json, os
def call(tool, args):
    r = subprocess.run(["ft2","call",tool,json.dumps(args)],capture_output=True,text=True)
    if r.returncode!=0:
        print("ERR",tool,r.stderr[:300]); return None
    try:
        out=json.loads(r.stdout)
        txt=out["content"][0]["text"]
        if out.get("isError"): print("TOOLERR",tool,txt[:200]); return None
        try: return json.loads(txt)
        except: return txt
    except Exception as e:
        print("parse fail",tool,r.stdout[:200]); return None
def new(name,ch=8): return call("module_new",{"channels":ch,"name":name})
def load(p): return call("module_load",{"path":p})
def setcell(p,r,c,note=None,inst=None,vol=None,eff=None,effp=None):
    a={"pattern":p,"row":r,"channel":c}
    if note is not None: a["note"]=note
    if inst is not None: a["instrument"]=inst
    if vol is not None: a["volume"]=vol
    if eff is not None: a["effect"]=eff
    if effp is not None: a["effect_param"]=effp
    return call("pattern_set_cell",a)
def plen(p,rows): return call("pattern_set_length",{"pattern":p,"rows":rows})
def clear(p): return call("pattern_clear",{"pattern":p})
def order(pos,pat): return call("order_set",{"position":pos,"pattern":pat})
def song(**kw): return call("song_set",kw)
def save(path): return call("module_save",{"path":path,"format":"xm"})
def render(path,loops=1,amp=20,start=0,stop=0):
    a={"path":path,"rate":44100,"bits":16,"amp":amp,"loops":loops}
    if start: a["start"]=start
    if stop: a["stop"]=stop
    return call("module_render",a)
def load_sample(path,inst,s=0): return call("sample_load",{"path":path,"instrument":inst,"sample":s})
def create_sample(inst,path,s=0,name=""):
    import base64
    b=base64.b64encode(open(path,'rb').read()).decode()
    return call("sample_create_from_pcm",{"instrument":inst,"sample":s,"pcm":b,"encoding":"int16","name":name})
def sample_set(inst,**kw):
    a={"instrument":inst}
    a.update(kw)
    return call("sample_set",a)
def inst_name(i,n): return call("instrument_set",{"instrument":i,"name":n})
def info(): return call("module_info",{})
